package com.howierux.mortalexpansion.data;
import com.howierux.mortalexpansion.catalog.*;
import net.minecraft.data.recipes.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.Ingredient;
import static net.minecraft.advancements.critereon.InventoryChangeTrigger.TriggerInstance.hasItems;
public final class EquipmentRecipes {
 public static void emit(RecipeOutput out){
  ShapedRecipeBuilder.shaped(RecipeCategory.BUILDING_BLOCKS,CatalogItems.GRAVE,3).pattern("GG").pattern("GG").pattern("GG").define('G',CatalogItems.GRAVESTONE).unlockedBy("has_gravestone",hasItems(CatalogItems.GRAVESTONE)).save(out,Catalog.id("grave"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.BLOODSTONE_AXE,1).pattern("BB").pattern("BS").pattern(" S").define('B',CatalogItems.BLOODSTONE).define('S',Items.STICK).unlockedBy("has_material",hasItems(CatalogItems.BLOODSTONE)).save(out,Catalog.id("bloodstone_axe"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.BLOODSTONE_BOOTS,1).pattern("B B").pattern("B B").define('B',CatalogItems.BLOODSTONE).unlockedBy("has_material",hasItems(CatalogItems.BLOODSTONE)).save(out,Catalog.id("bloodstone_boots"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.BLOODSTONE_CHESTPLATE,1).pattern("B B").pattern("BBB").pattern("BBB").define('B',CatalogItems.BLOODSTONE).unlockedBy("has_material",hasItems(CatalogItems.BLOODSTONE)).save(out,Catalog.id("bloodstone_chestplate"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.BLOODSTONE_HELMET,1).pattern("BBB").pattern("B B").define('B',CatalogItems.BLOODSTONE).unlockedBy("has_material",hasItems(CatalogItems.BLOODSTONE)).save(out,Catalog.id("bloodstone_helmet"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.BLOODSTONE_HOE,1).pattern("BB").pattern(" S").pattern(" S").define('B',CatalogItems.BLOODSTONE).define('S',Items.STICK).unlockedBy("has_material",hasItems(CatalogItems.BLOODSTONE)).save(out,Catalog.id("bloodstone_hoe"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.BLOODSTONE_LEGGINGS,1).pattern("BBB").pattern("B B").pattern("B B").define('B',CatalogItems.BLOODSTONE).unlockedBy("has_material",hasItems(CatalogItems.BLOODSTONE)).save(out,Catalog.id("bloodstone_leggings"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.BLOODSTONE_PICKAXE,1).pattern("BBB").pattern(" S ").pattern(" S ").define('B',CatalogItems.BLOODSTONE).define('S',Items.STICK).unlockedBy("has_material",hasItems(CatalogItems.BLOODSTONE)).save(out,Catalog.id("bloodstone_pickaxe"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.BLOODSTONE_SHOVEL,1).pattern("B").pattern("S").pattern("S").define('B',CatalogItems.BLOODSTONE).define('S',Items.STICK).unlockedBy("has_material",hasItems(CatalogItems.BLOODSTONE)).save(out,Catalog.id("bloodstone_shovel"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.BLOODSTONE_SWORD,1).pattern("B").pattern("B").pattern("S").define('B',CatalogItems.BLOODSTONE).define('S',Items.STICK).unlockedBy("has_material",hasItems(CatalogItems.BLOODSTONE)).save(out,Catalog.id("bloodstone_sword"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.GRAVESTONE_SWORD,1).pattern("G").pattern("G").pattern("S").define('G',CatalogItems.GRAVESTONE).define('S',Items.STICK).unlockedBy("has_material",hasItems(CatalogItems.GRAVESTONE)).save(out,Catalog.id("gravestone_sword"));
  ShapedRecipeBuilder.shaped(RecipeCategory.TOOLS,CatalogItems.PURIFIED_GRAVESTONE_SWORD,1).pattern("G").pattern("G").pattern("S").define('G',CatalogItems.PURIFIED_GRAVESTONE).define('S',Items.STICK).unlockedBy("has_material",hasItems(CatalogItems.PURIFIED_GRAVESTONE)).save(out,Catalog.id("purified_gravestone_sword"));
  SmithingTransformRecipeBuilder.smithing(Ingredient.of(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),Ingredient.of(CatalogItems.BLOODSTONE_AXE),Ingredient.of(Items.NETHERITE_INGOT),RecipeCategory.TOOLS,CatalogItems.SPECTRALITE_AXE).unlocks("has_base",hasItems(CatalogItems.BLOODSTONE_AXE)).save(out,Catalog.id("spectralite_axe_smithing"));
  SmithingTransformRecipeBuilder.smithing(Ingredient.of(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),Ingredient.of(CatalogItems.BLOODSTONE_BOOTS),Ingredient.of(Items.NETHERITE_INGOT),RecipeCategory.TOOLS,CatalogItems.SPECTRALITE_BOOTS).unlocks("has_base",hasItems(CatalogItems.BLOODSTONE_BOOTS)).save(out,Catalog.id("spectralite_boots_smithing"));
  SmithingTransformRecipeBuilder.smithing(Ingredient.of(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),Ingredient.of(CatalogItems.BLOODSTONE_CHESTPLATE),Ingredient.of(Items.NETHERITE_INGOT),RecipeCategory.TOOLS,CatalogItems.SPECTRALITE_CHESTPLATE).unlocks("has_base",hasItems(CatalogItems.BLOODSTONE_CHESTPLATE)).save(out,Catalog.id("spectralite_chestplate_smithing"));
  SmithingTransformRecipeBuilder.smithing(Ingredient.of(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),Ingredient.of(CatalogItems.BLOODSTONE_HELMET),Ingredient.of(Items.NETHERITE_INGOT),RecipeCategory.TOOLS,CatalogItems.SPECTRALITE_HELMET).unlocks("has_base",hasItems(CatalogItems.BLOODSTONE_HELMET)).save(out,Catalog.id("spectralite_helmet_smithing"));
  SmithingTransformRecipeBuilder.smithing(Ingredient.of(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),Ingredient.of(CatalogItems.BLOODSTONE_HOE),Ingredient.of(Items.NETHERITE_INGOT),RecipeCategory.TOOLS,CatalogItems.SPECTRALITE_HOE).unlocks("has_base",hasItems(CatalogItems.BLOODSTONE_HOE)).save(out,Catalog.id("spectralite_hoe_smithing"));
  SmithingTransformRecipeBuilder.smithing(Ingredient.of(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),Ingredient.of(CatalogItems.BLOODSTONE_LEGGINGS),Ingredient.of(Items.NETHERITE_INGOT),RecipeCategory.TOOLS,CatalogItems.SPECTRALITE_LEGGINGS).unlocks("has_base",hasItems(CatalogItems.BLOODSTONE_LEGGINGS)).save(out,Catalog.id("spectralite_leggings_smithing"));
  SmithingTransformRecipeBuilder.smithing(Ingredient.of(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),Ingredient.of(CatalogItems.BLOODSTONE_PICKAXE),Ingredient.of(Items.NETHERITE_INGOT),RecipeCategory.TOOLS,CatalogItems.SPECTRALITE_PICKAXE).unlocks("has_base",hasItems(CatalogItems.BLOODSTONE_PICKAXE)).save(out,Catalog.id("spectralite_pickaxe_smithing"));
  SmithingTransformRecipeBuilder.smithing(Ingredient.of(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),Ingredient.of(CatalogItems.BLOODSTONE_SHOVEL),Ingredient.of(Items.NETHERITE_INGOT),RecipeCategory.TOOLS,CatalogItems.SPECTRALITE_SHOVEL).unlocks("has_base",hasItems(CatalogItems.BLOODSTONE_SHOVEL)).save(out,Catalog.id("spectralite_shovel_smithing"));
  SmithingTransformRecipeBuilder.smithing(Ingredient.of(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),Ingredient.of(CatalogItems.BLOODSTONE_SWORD),Ingredient.of(Items.NETHERITE_INGOT),RecipeCategory.TOOLS,CatalogItems.SPECTRALITE_SWORD).unlocks("has_base",hasItems(CatalogItems.BLOODSTONE_SWORD)).save(out,Catalog.id("spectralite_sword_smithing"));
 }
}
